const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  function getInfoAsync(obj) {
    return new Promise((resolve, reject) => {
      obj.getInfo((res, err) => {
        if (err) reject(err);
        else resolve(res);
      });
    });
  }

  // 1. Geometry & Time Definitions
  const canada = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'Canada'))
    .geometry();

  const startMonth = 1;
  const startDay = 1;
  const endMonth = 8;
  const endDay = 3;

  async function yearStats(year) {
    const dateStart = ee.Date.fromYMD(year, 1, 1);
    const dateEnd = ee.Date.fromYMD(year, 12, 31);

    const doyEnd = ee.Number(
      ee.Date.fromYMD(year, endMonth, endDay).difference(ee.Date.fromYMD(year, 1, 1), 'day')
    ).add(1);

    async function tryDataset(datasetId) {
      const col = ee.ImageCollection(datasetId)
        .filterDate(dateStart, dateEnd)
        .select('BurnDate');

      const size = await getInfoAsync(col.size());
      return { col, size, datasetId };
    }

    // Try MODIS/061 first, then 006 as fallback
    let attempt = await tryDataset('MODIS/061/MCD64A1');
    if (attempt.size === 0) {
      const fallback = await tryDataset('MODIS/006/MCD64A1');
      if (fallback.size === 0) {
        return { status: 'C1', details: `Year ${year}: No images in 061 or 006.` };
      }
      attempt = fallback;
    }

    // Build annual BurnDate image (max BurnDate across months to ensure presence)
    const annualBD = attempt.col.max().rename('BurnDate');

    // Mask burned pixels up to DOY cutoff
    const mask = annualBD.gt(0).and(annualBD.lte(doyEnd));
    const burnedBD = annualBD.updateMask(mask);

    // Count valid burned pixels
    const pixCount = await getInfoAsync(
      burnedBD.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: canada,
        scale: 1000,
        maxPixels: 1e13,
        tileScale: 4,
      }).get('BurnDate')
    );

    if (!pixCount || pixCount === 0) {
      return {
        status: 'C2',
        details: `Year ${year}: Images exist (dataset=${attempt.datasetId}, imgs=${attempt.size}), but no valid burned pixels by DOY<=${await getInfoAsync(doyEnd)}.`,
      };
    }

    // Area (km2)
    const areaSqm = await getInfoAsync(
      ee.Image.pixelArea().updateMask(mask).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: canada,
        scale: 1000,
        maxPixels: 1e13,
        tileScale: 4,
      }).get('area')
    );

    const doyEndNum = await getInfoAsync(doyEnd);
    if (areaSqm === null || areaSqm === undefined || !isFinite(areaSqm) || areaSqm < 0) {
      return { status: 'C3', details: `Year ${year}: Invalid area.` };
    }

    const areaKm2 = areaSqm / 1e6;

    return {
      status: 'OK',
      year,
      dataset: attempt.datasetId,
      imgs: attempt.size,
      doyEnd: doyEndNum,
      pixels: pixCount,
      areaKm2,
    };
  }

  try {
    const s2023 = await yearStats(2023);
    if (s2023.status !== 'OK') {
      console.log(s2023.details || `2023 status: ${s2023.status}`);
      console.log('C1' === s2023.status ? 'C1' : s2023.status);
      return;
    }
    const s2025 = await yearStats(2025);
    if (s2025.status !== 'OK') {
      console.log(s2025.details || `2025 status: ${s2025.status}`);
      console.log('C1' === s2025.status ? 'C1' : s2025.status);
      return;
    }

    // Evidence output (concise)
    console.log(`2023: dataset=${s2023.dataset}, imgs=${s2023.imgs}, DOY<=${s2023.doyEnd}, burned_px=${s2023.pixels}, area_km2=${s2023.areaKm2.toFixed(0)}`);
    console.log(`2025: dataset=${s2025.dataset}, imgs=${s2025.imgs}, DOY<=${s2025.doyEnd}, burned_px=${s2025.pixels}, area_km2=${s2025.areaKm2.toFixed(0)}`);

    const ratio = s2025.areaKm2 / (s2023.areaKm2 > 0 ? s2023.areaKm2 : 1);
    console.log(`Ratio 2025/2023: ${ratio.toFixed(3)}`);

    // Final Answer
    if (!isFinite(s2023.areaKm2) || !isFinite(s2025.areaKm2)) {
      console.log('C3');
      return;
    }
    console.log(s2025.areaKm2 > s2023.areaKm2 ? 'A' : 'B');
  } catch (err) {
    // Unexpected errors (e.g., dataset/band name or memory issues)
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
